import{i as e,r as t,s as n,t as r}from"./app-Ci0u99L5.js";var i=JSON.parse(`{"path":"/guide/gin/","title":"HTTP API на Gin","lang":"ru-RU","frontmatter":{"prev":"/guide/http-server/best-practices.md","next":"/guide/gin/tests.md"},"git":{"updatedTime":1791920488000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"50b56faa27d34a912848aea3721eb869efc292fe","time":1791920488000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"docs: added chapter 30"}]},"filePathRelative":"guide/gin/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="http-api-на-gin" tabindex="-1"><a class="header-anchor" href="#http-api-на-gin"><span>HTTP API на Gin</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Перенести HTTP-слой Task Manager API со стандартного <code>net/http</code> на Gin, не изменяя service и repository. Научиться регистрировать маршруты, извлекать параметры, читать JSON, писать middleware для request ID и структурированного access log, восстанавливаться после panic и тестировать Gin handlers через <code>httptest</code>.</p><p>Gin — популярный HTTP-фреймворк Go. Он работает поверх стандартных типов <code>net/http</code>: сервер всё так же получает HTTP-запрос и отправляет HTTP-ответ. Gin добавляет более компактную маршрутизацию, <code>gin.Context</code>, binding JSON и удобный механизм middleware.</p><p>В предыдущей главе API работал через <code>http.ServeMux</code>. Теперь заменим <strong>только transport-слой</strong>:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">было:  net/http handler → service → repository / TaskStore</span>
<span class="line">стало: Gin handler      → service → repository / TaskStore</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>TaskService</code>, правила создания задач, ошибки Store и способ хранения задач не должны меняться. Это главный результат разделения слоёв.</p><h2 id="установка-gin" tabindex="-1"><a class="header-anchor" href="#установка-gin"><span>Установка Gin</span></a></h2><p>В корне Task Manager API добавьте зависимость:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go get github.com/gin-gonic/gin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Go добавит Gin и его версии зависимостей в <code>go.mod</code> и <code>go.sum</code>. Не редактируйте эти файлы вручную. Проверить сборку можно так:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go <span class="token builtin class-name">test</span> ./<span class="token punctuation">..</span>.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="первыи-router" tabindex="-1"><a class="header-anchor" href="#первыи-router"><span>Первый router</span></a></h2><p>Вместо <code>http.NewServeMux</code> создайте <code>gin.Engine</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span>gin<span class="token punctuation">.</span>Engine <span class="token punctuation">{</span></span>
<span class="line">	router <span class="token operator">:=</span> gin<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">GET</span><span class="token punctuation">(</span><span class="token string">&quot;/healthz&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>health<span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">GET</span><span class="token punctuation">(</span><span class="token string">&quot;/tasks&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>listTasks<span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">POST</span><span class="token punctuation">(</span><span class="token string">&quot;/tasks&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>createTask<span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">POST</span><span class="token punctuation">(</span><span class="token string">&quot;/tasks/:id/complete&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>completeTask<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> router</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>gin.Default()</code> автоматически добавляет встроенные middleware <code>gin.Logger()</code> и <code>gin.Recovery()</code>. В этой главе используем <code>gin.New()</code>, чтобы явно подключить middleware и писать access log через уже знакомый <code>log/slog</code>.</p><p>Сравнение маршрута:</p><table><thead><tr><th><code>net/http</code></th><th>Gin</th></tr></thead><tbody><tr><td><code>mux.HandleFunc(&quot;GET /tasks&quot;, api.listTasks)</code></td><td><code>router.GET(&quot;/tasks&quot;, api.listTasks)</code></td></tr><tr><td><code>mux.HandleFunc(&quot;POST /tasks/{id}/complete&quot;, api.completeTask)</code></td><td><code>router.POST(&quot;/tasks/:id/complete&quot;, api.completeTask)</code></td></tr><tr><td><code>r.PathValue(&quot;id&quot;)</code></td><td><code>c.Param(&quot;id&quot;)</code></td></tr></tbody></table><p>В Gin path-параметр записывают как <code>:id</code>, а не <code>{id}</code>.</p><h2 id="gin-context-и-context-context" tabindex="-1"><a class="header-anchor" href="#gin-context-и-context-context"><span><code>gin.Context</code> и <code>context.Context</code></span></a></h2><p>Handler Gin получает <code>*gin.Context</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">listTasks</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>*gin.Context</code> — объект Gin для текущего HTTP-обмена. Через него получают параметры, query, body и формируют ответ. Это <strong>не</strong> тот же тип, что стандартный <code>context.Context</code>.</p><p>Для service всё ещё нужен стандартный context из исходного HTTP-запроса:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">tasks<span class="token punctuation">,</span> err <span class="token operator">:=</span> api<span class="token punctuation">.</span>service<span class="token punctuation">.</span><span class="token function">List</span><span class="token punctuation">(</span>c<span class="token punctuation">.</span>Request<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Не передавайте <code>*gin.Context</code> в service, repository или <code>database/sql</code>. Это привяжет бизнес-логику к Gin и усложнит тестирование или будущую замену фреймворка.</p><h2 id="json-ответы" tabindex="-1"><a class="header-anchor" href="#json-ответы"><span>JSON-ответы</span></a></h2><p>В <code>net/http</code> мы устанавливали заголовок, статус и вызывали <code>json.NewEncoder</code>. В Gin эту работу делает <code>c.JSON</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">health</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	c<span class="token punctuation">.</span><span class="token function">JSON</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusOK<span class="token punctuation">,</span> gin<span class="token punctuation">.</span>H<span class="token punctuation">{</span><span class="token string">&quot;status&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;ok&quot;</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> errorResponse <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Error <span class="token builtin">string</span> <span class="token string">\`json:&quot;error&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">writeError</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> status <span class="token builtin">int</span><span class="token punctuation">,</span> message <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	c<span class="token punctuation">.</span><span class="token function">JSON</span><span class="token punctuation">(</span>status<span class="token punctuation">,</span> errorResponse<span class="token punctuation">{</span>Error<span class="token punctuation">:</span> message<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Gin устанавливает JSON <code>Content-Type</code> и сериализует значение. <code>gin.H</code> — короткая запись для <code>map[string]any</code>; для стабильного публичного контракта ошибок лучше оставить отдельную структуру <code>errorResponse</code>.</p><h2 id="группы-маршрутов" tabindex="-1"><a class="header-anchor" href="#группы-маршрутов"><span>Группы маршрутов</span></a></h2><p>Когда API разрастётся, маршруты удобно объединить общим префиксом:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span>gin<span class="token punctuation">.</span>Engine <span class="token punctuation">{</span></span>
<span class="line">	router <span class="token operator">:=</span> gin<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">GET</span><span class="token punctuation">(</span><span class="token string">&quot;/healthz&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>health<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	v1 <span class="token operator">:=</span> router<span class="token punctuation">.</span><span class="token function">Group</span><span class="token punctuation">(</span><span class="token string">&quot;/api/v1&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	v1<span class="token punctuation">.</span><span class="token function">GET</span><span class="token punctuation">(</span><span class="token string">&quot;/version&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>version<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> router</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Группа не создаёт новый сервер: она только добавляет общий путь и позволяет назначить middleware всем маршрутам внутри неё. Она пригодится, если позже появится версионирование, например <code>/api/v1</code>. При миграции в этой главе сохраняем публичные URL версии на <code>net/http</code>: цель — сравнить Gin со стандартной библиотекой, а не одновременно изменить контракт для клиентов.</p><p>Контракт маршрутов после миграции:</p><table><thead><tr><th>Метод и путь</th><th>Ответ при успехе</th></tr></thead><tbody><tr><td><code>GET /healthz</code></td><td><code>200 OK</code> и <code>{&quot;status&quot;:&quot;ok&quot;}</code></td></tr><tr><td><code>GET /tasks</code></td><td><code>200 OK</code> и массив задач</td></tr><tr><td><code>POST /tasks</code></td><td><code>201 Created</code> и новая задача</td></tr><tr><td><code>POST /tasks/:id/complete</code></td><td><code>200 OK</code> и выполненная задача</td></tr></tbody></table><h2 id="входнои-json-и-binding" tabindex="-1"><a class="header-anchor" href="#входнои-json-и-binding"><span>Входной JSON и binding</span></a></h2><p>Gin умеет связывать JSON-body со структурой через <code>ShouldBindJSON</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> createTaskRequest <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Title    <span class="token builtin">string</span> <span class="token string">\`json:&quot;title&quot; binding:&quot;required&quot;\`</span></span>
<span class="line">	Priority <span class="token builtin">int</span>    <span class="token string">\`json:&quot;priority&quot; binding:&quot;required,gte=1,lte=5&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Теги <code>binding</code> проверяют обязательность и диапазон. Но <code>required</code> для числа означает «не ноль». Это подходит для приоритета от 1 до 5; если <code>0</code> — допустимое значение, нужна другая модель валидации.</p><p>Handler создания задачи:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">createTask</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> request createTaskRequest</span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> c<span class="token punctuation">.</span><span class="token function">ShouldBindJSON</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>request<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;некорректные данные задачи&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	request<span class="token punctuation">.</span>Title <span class="token operator">=</span> strings<span class="token punctuation">.</span><span class="token function">TrimSpace</span><span class="token punctuation">(</span>request<span class="token punctuation">.</span>Title<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> request<span class="token punctuation">.</span>Title <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;название задачи обязательно&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	createdTask<span class="token punctuation">,</span> err <span class="token operator">:=</span> api<span class="token punctuation">.</span>service<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>c<span class="token punctuation">.</span>Request<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> task<span class="token punctuation">.</span>CreateInput<span class="token punctuation">{</span></span>
<span class="line">		Title<span class="token punctuation">:</span>    request<span class="token punctuation">.</span>Title<span class="token punctuation">,</span></span>
<span class="line">		Priority<span class="token punctuation">:</span> request<span class="token punctuation">.</span>Priority<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		api<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось создать задачу&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> <span class="token string">&quot;внутренняя ошибка сервера&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	api<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">&quot;задача создана&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;task_id&quot;</span><span class="token punctuation">,</span> createdTask<span class="token punctuation">.</span>ID<span class="token punctuation">)</span></span>
<span class="line">	c<span class="token punctuation">.</span><span class="token function">JSON</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusCreated<span class="token punctuation">,</span> createdTask<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для HTTP-запроса лучше использовать <code>ShouldBindJSON</code>, а не <code>BindJSON</code>: первый вариант возвращает ошибку и оставляет handler полный контроль над единым JSON-форматом ошибки. Передавать <code>id</code> и <code>completed</code> по-прежнему нельзя: <code>createTaskRequest</code> содержит только разрешённые поля.</p><div class="hint-container warning"><p class="hint-container-title">Строгость неизвестных полей</p><p><code>ShouldBindJSON</code> по умолчанию может проигнорировать незнакомое поле. Если контракт API требует той же строгости, что в главе о <code>net/http</code>, включите её при настройке router:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">gin<span class="token punctuation">.</span><span class="token function">EnableJsonDecoderDisallowUnknownFields</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Эта настройка глобальна для Gin-процесса. Включайте её один раз при запуске приложения и убедитесь тестом, что API действительно отвергает опечатки клиента.</p></div><h2 id="параметры-статусы-и-доменные-ошибки" tabindex="-1"><a class="header-anchor" href="#параметры-статусы-и-доменные-ошибки"><span>Параметры, статусы и доменные ошибки</span></a></h2><p>Извлечём <code>id</code>, завершим задачу и сохраним прежний HTTP-контракт:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">completeTask</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	id<span class="token punctuation">,</span> err <span class="token operator">:=</span> strconv<span class="token punctuation">.</span><span class="token function">Atoi</span><span class="token punctuation">(</span>c<span class="token punctuation">.</span><span class="token function">Param</span><span class="token punctuation">(</span><span class="token string">&quot;id&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">||</span> id <span class="token operator">&lt;</span> <span class="token number">1</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;идентификатор задачи должен быть положительным числом&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	completedTask<span class="token punctuation">,</span> err <span class="token operator">:=</span> api<span class="token punctuation">.</span>service<span class="token punctuation">.</span><span class="token function">Complete</span><span class="token punctuation">(</span>c<span class="token punctuation">.</span>Request<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> id<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> store<span class="token punctuation">.</span>ErrTaskNotFound<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusNotFound<span class="token punctuation">,</span> <span class="token string">&quot;задача не найдена&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		api<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось завершить задачу&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;task_id&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> <span class="token string">&quot;внутренняя ошибка сервера&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	c<span class="token punctuation">.</span><span class="token function">JSON</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusOK<span class="token punctuation">,</span> completedTask<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Gin делает извлечение маршрута короче, но ответственность не меняется: handler проверяет форму входа и переводит известные ошибки домена в HTTP-статусы; service хранит бизнес-логику.</p><h2 id="middleware-общая-обвязка-запроса" tabindex="-1"><a class="header-anchor" href="#middleware-общая-обвязка-запроса"><span>Middleware: общая обвязка запроса</span></a></h2><p>Middleware получает <code>*gin.Context</code>, выполняется до и/или после handler и вызывает <code>c.Next()</code>, чтобы передать управление дальше:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">exampleMiddleware</span><span class="token punctuation">(</span><span class="token punctuation">)</span> gin<span class="token punctuation">.</span>HandlerFunc <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token keyword">func</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token comment">// До handler.</span></span>
<span class="line">		c<span class="token punctuation">.</span><span class="token function">Next</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token comment">// После handler.</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Порядок <code>router.Use</code> важен. Middleware, зарегистрированный раньше, начинает выполняться раньше и завершает часть «после handler» позже — как вложенные <code>defer</code>.</p><h3 id="request-id" tabindex="-1"><a class="header-anchor" href="#request-id"><span>Request ID</span></a></h3><p>Каждому запросу полезен идентификатор: по нему можно связать access log, application log и сообщение об ошибке. Клиент может прислать <code>X-Request-ID</code>; если заголовка нет, сервер генерирует случайное значение.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">const</span> <span class="token punctuation">(</span></span>
<span class="line">	requestIDKey       <span class="token operator">=</span> <span class="token string">&quot;request_id&quot;</span></span>
<span class="line">	maxRequestIDLength <span class="token operator">=</span> <span class="token number">128</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Чтобы не вводить дополнительную зависимость только ради ID, используем стандартные <code>crypto/rand</code> и <code>encoding/hex</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">newRequestID</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	bytes <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span><span class="token punctuation">,</span> <span class="token number">16</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> rand<span class="token punctuation">.</span><span class="token function">Read</span><span class="token punctuation">(</span>bytes<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span> err</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> hex<span class="token punctuation">.</span><span class="token function">EncodeToString</span><span class="token punctuation">(</span>bytes<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Полный middleware должен обработать редкую ошибку генератора и не продолжать запрос без ID:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">requestID</span><span class="token punctuation">(</span><span class="token punctuation">)</span> gin<span class="token punctuation">.</span>HandlerFunc <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token keyword">func</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		id <span class="token operator">:=</span> c<span class="token punctuation">.</span><span class="token function">GetHeader</span><span class="token punctuation">(</span><span class="token string">&quot;X-Request-ID&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span> <span class="token operator">&gt;</span> maxRequestIDLength <span class="token punctuation">{</span></span>
<span class="line">			<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;слишком длинный X-Request-ID&quot;</span><span class="token punctuation">)</span></span>
<span class="line">			c<span class="token punctuation">.</span><span class="token function">Abort</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">			<span class="token keyword">return</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">		<span class="token keyword">if</span> id <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">			<span class="token keyword">var</span> err <span class="token builtin">error</span></span>
<span class="line">			id<span class="token punctuation">,</span> err <span class="token operator">=</span> <span class="token function">newRequestID</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">			<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">				<span class="token function">writeError</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> <span class="token string">&quot;не удалось подготовить запрос&quot;</span><span class="token punctuation">)</span></span>
<span class="line">				c<span class="token punctuation">.</span><span class="token function">Abort</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">				<span class="token keyword">return</span></span>
<span class="line">			<span class="token punctuation">}</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">		c<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span>requestIDKey<span class="token punctuation">,</span> id<span class="token punctuation">)</span></span>
<span class="line">		c<span class="token punctuation">.</span><span class="token function">Header</span><span class="token punctuation">(</span><span class="token string">&quot;X-Request-ID&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">)</span></span>
<span class="line">		c<span class="token punctuation">.</span><span class="token function">Next</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>c.Abort()</code> останавливает оставшиеся handlers текущей цепочки. Не вызывайте <code>c.Next()</code> после него. Ограничение длины не позволяет передать в логи произвольно большой заголовок от клиента.</p><h3 id="структурированныи-access-log" tabindex="-1"><a class="header-anchor" href="#структурированныи-access-log"><span>Структурированный access log</span></a></h3><p>Используем <code>slog</code>, чтобы access log был пригоден для поиска и машинной обработки:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">accessLog</span><span class="token punctuation">(</span>logger <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger<span class="token punctuation">)</span> gin<span class="token punctuation">.</span>HandlerFunc <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token keyword">func</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		startedAt <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">		c<span class="token punctuation">.</span><span class="token function">Next</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">		requestID<span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">:=</span> c<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>requestIDKey<span class="token punctuation">)</span></span>
<span class="line">		logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span></span>
<span class="line">			<span class="token string">&quot;HTTP-запрос завершён&quot;</span><span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;request_id&quot;</span><span class="token punctuation">,</span> requestID<span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;method&quot;</span><span class="token punctuation">,</span> c<span class="token punctuation">.</span>Request<span class="token punctuation">.</span>Method<span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;path&quot;</span><span class="token punctuation">,</span> c<span class="token punctuation">.</span>Request<span class="token punctuation">.</span>URL<span class="token punctuation">.</span>Path<span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;status&quot;</span><span class="token punctuation">,</span> c<span class="token punctuation">.</span>Writer<span class="token punctuation">.</span><span class="token function">Status</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;duration&quot;</span><span class="token punctuation">,</span> time<span class="token punctuation">.</span><span class="token function">Since</span><span class="token punctuation">(</span>startedAt<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Лог пишется после <code>c.Next()</code>, поэтому в него попадает итоговый статус. Значение из <code>c.Get</code> имеет тип <code>any</code>: middleware не должен паниковать, если ID отсутствует по ошибке конфигурации. В production можно дополнить запись размером ответа и IP клиента, но не логируйте тело запроса с паролями, токенами или персональными данными.</p><h3 id="recovery" tabindex="-1"><a class="header-anchor" href="#recovery"><span>Recovery</span></a></h3><p>Panic не должен завершать весь HTTP-сервер. Gin содержит <code>gin.Recovery()</code> — middleware, который перехватывает panic, пишет её в <code>stderr</code> и отвечает <code>500</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">router<span class="token punctuation">.</span><span class="token function">Use</span><span class="token punctuation">(</span>gin<span class="token punctuation">.</span><span class="token function">Recovery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>В production чаще нужен структурированный лог panic. Тогда можно применить <code>gin.CustomRecovery</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">recovery</span><span class="token punctuation">(</span>logger <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger<span class="token punctuation">)</span> gin<span class="token punctuation">.</span>HandlerFunc <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> gin<span class="token punctuation">.</span><span class="token function">CustomRecovery</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> recovered any<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;panic в HTTP handler&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;recovered&quot;</span><span class="token punctuation">,</span> recovered<span class="token punctuation">)</span></span>
<span class="line">		c<span class="token punctuation">.</span><span class="token function">AbortWithStatusJSON</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> errorResponse<span class="token punctuation">{</span></span>
<span class="line">			Error<span class="token punctuation">:</span> <span class="token string">&quot;внутренняя ошибка сервера&quot;</span><span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не используйте recovery для ожидаемых ошибок валидации или доступа к данным. Он нужен как последняя защита от ошибок программирования; причину panic всё равно нужно исправить и закрепить тестом.</p><h2 id="собираем-router" tabindex="-1"><a class="header-anchor" href="#собираем-router"><span>Собираем router</span></a></h2><p>Создадим middleware один раз при построении router:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span>gin<span class="token punctuation">.</span>Engine <span class="token punctuation">{</span></span>
<span class="line">	router <span class="token operator">:=</span> gin<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">Use</span><span class="token punctuation">(</span><span class="token function">requestID</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">Use</span><span class="token punctuation">(</span><span class="token function">accessLog</span><span class="token punctuation">(</span>api<span class="token punctuation">.</span>logger<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">Use</span><span class="token punctuation">(</span><span class="token function">recovery</span><span class="token punctuation">(</span>api<span class="token punctuation">.</span>logger<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">GET</span><span class="token punctuation">(</span><span class="token string">&quot;/healthz&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>health<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">GET</span><span class="token punctuation">(</span><span class="token string">&quot;/tasks&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>listTasks<span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">POST</span><span class="token punctuation">(</span><span class="token string">&quot;/tasks&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>createTask<span class="token punctuation">)</span></span>
<span class="line">	router<span class="token punctuation">.</span><span class="token function">POST</span><span class="token punctuation">(</span><span class="token string">&quot;/tasks/:id/complete&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>completeTask<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> router</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Порядок выбран осознанно:</p><ol><li><code>requestID</code> добавляет ID в context и response header;</li><li><code>accessLog</code> измеряет всю последующую обработку и видит итоговый статус;</li><li><code>recovery</code> преобразует panic в ответ <code>500</code>;</li><li>handler выполняет бизнес-сценарий.</li></ol><h2 id="запуск-приложения" tabindex="-1"><a class="header-anchor" href="#запуск-приложения"><span>Запуск приложения</span></a></h2><p><code>*gin.Engine</code> реализует <code>http.Handler</code>, поэтому сборка <code>http.Server</code> почти не меняется:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">server <span class="token operator">:=</span> <span class="token operator">&amp;</span>http<span class="token punctuation">.</span>Server<span class="token punctuation">{</span></span>
<span class="line">	Addr<span class="token punctuation">:</span>              <span class="token string">&quot;:8080&quot;</span><span class="token punctuation">,</span></span>
<span class="line">	Handler<span class="token punctuation">:</span>           api<span class="token punctuation">.</span><span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">	ReadHeaderTimeout<span class="token punctuation">:</span> <span class="token number">5</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">:=</span> server<span class="token punctuation">.</span><span class="token function">ListenAndServe</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> http<span class="token punctuation">.</span>ErrServerClosed<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP-сервер завершился с ошибкой&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не используйте <code>router.Run()</code> в финальном <code>main</code>: он создаёт сервер сам и не даёт централизованно задать <code>http.Server</code>. Таймауты и graceful shutdown добавим в следующей главе о жизненном цикле.</p><h2 id="тестирование-gin-handler" tabindex="-1"><a class="header-anchor" href="#тестирование-gin-handler"><span>Тестирование Gin handler</span></a></h2><p>Gin также совместим с <code>httptest</code>: запуска сервера и реального порта не требуется. В тестах установите release mode, чтобы не видеть debug output Gin:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestCreateTask</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	gin<span class="token punctuation">.</span><span class="token function">SetMode</span><span class="token punctuation">(</span>gin<span class="token punctuation">.</span>TestMode<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	service <span class="token operator">:=</span> <span class="token operator">&amp;</span>fakeTaskService<span class="token punctuation">{</span></span>
<span class="line">		createdTask<span class="token punctuation">:</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span> Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	api <span class="token operator">:=</span> <span class="token function">New</span><span class="token punctuation">(</span>service<span class="token punctuation">,</span> <span class="token function">newTestLogger</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	request <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewRequest</span><span class="token punctuation">(</span></span>
<span class="line">		http<span class="token punctuation">.</span>MethodPost<span class="token punctuation">,</span></span>
<span class="line">		<span class="token string">&quot;/tasks&quot;</span><span class="token punctuation">,</span></span>
<span class="line">		strings<span class="token punctuation">.</span><span class="token function">NewReader</span><span class="token punctuation">(</span><span class="token string">\`{&quot;title&quot;:&quot;Купить молоко&quot;,&quot;priority&quot;:2}\`</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">)</span></span>
<span class="line">	request<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;X-Request-ID&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;test-request-1&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	recorder <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewRecorder</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	api<span class="token punctuation">.</span><span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ServeHTTP</span><span class="token punctuation">(</span>recorder<span class="token punctuation">,</span> request<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> recorder<span class="token punctuation">.</span>Code <span class="token operator">!=</span> http<span class="token punctuation">.</span>StatusCreated <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;status = %d, ожидался %d&quot;</span><span class="token punctuation">,</span> recorder<span class="token punctuation">.</span>Code<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusCreated<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> got <span class="token operator">:=</span> recorder<span class="token punctuation">.</span><span class="token function">Header</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;X-Request-ID&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> got <span class="token operator">!=</span> <span class="token string">&quot;test-request-1&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;X-Request-ID = %q&quot;</span><span class="token punctuation">,</span> got<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> got task<span class="token punctuation">.</span>Task</span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">NewDecoder</span><span class="token punctuation">(</span>recorder<span class="token punctuation">.</span>Body<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Decode</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>got<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось прочитать JSON-ответ: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> got <span class="token operator">!=</span> service<span class="token punctuation">.</span>createdTask <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;ответ = %+v, ожидалось %+v&quot;</span><span class="token punctuation">,</span> got<span class="token punctuation">,</span> service<span class="token punctuation">.</span>createdTask<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Тест проверяет тот же HTTP-контракт, что и версия на <code>net/http</code>, а также поведение middleware. Fake service остаётся прежним: Gin не проник в бизнес-логику.</p><h2 id="сравнение-с-net-http" tabindex="-1"><a class="header-anchor" href="#сравнение-с-net-http"><span>Сравнение с <code>net/http</code></span></a></h2><table><thead><tr><th>Задача</th><th><code>net/http</code></th><th>Gin</th></tr></thead><tbody><tr><td>Router</td><td><code>http.NewServeMux()</code></td><td><code>gin.New()</code></td></tr><tr><td>Маршрут</td><td><code>&quot;POST /tasks/{id}/complete&quot;</code></td><td><code>POST(&quot;/tasks/:id/complete&quot;, ...)</code></td></tr><tr><td>Параметр пути</td><td><code>r.PathValue(&quot;id&quot;)</code></td><td><code>c.Param(&quot;id&quot;)</code></td></tr><tr><td>JSON-ответ</td><td>helper + <code>json.Encoder</code></td><td><code>c.JSON(status, value)</code></td></tr><tr><td>JSON-body</td><td><code>json.Decoder</code> + ручная проверка</td><td><code>c.ShouldBindJSON(&amp;request)</code> + теги</td></tr><tr><td>Middleware</td><td>собственная обёртка <code>http.Handler</code></td><td><code>router.Use(...)</code></td></tr><tr><td>Тест</td><td><code>httptest</code></td><td>тот же <code>httptest</code></td></tr></tbody></table><p>Gin уменьшает объём транспортного кода, но не отменяет HTTP: по-прежнему нужно выбирать статусы, валидировать вход, передавать context и не раскрывать внутренние ошибки.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="передавать-gin-context-в-service" tabindex="-1"><a class="header-anchor" href="#передавать-gin-context-в-service"><span>Передавать <code>*gin.Context</code> в service</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token comment">// Плохо: service теперь зависит от Gin.</span></span>
<span class="line">api<span class="token punctuation">.</span>service<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> input<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Передавайте <code>c.Request.Context()</code>.</p><h3 id="использовать-gin-default-вместе-со-своими-logger-и-recovery" tabindex="-1"><a class="header-anchor" href="#использовать-gin-default-вместе-со-своими-logger-и-recovery"><span>Использовать <code>gin.Default()</code> вместе со своими logger и recovery</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">router <span class="token operator">:=</span> gin<span class="token punctuation">.</span><span class="token function">Default</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">router<span class="token punctuation">.</span><span class="token function">Use</span><span class="token punctuation">(</span><span class="token function">accessLog</span><span class="token punctuation">(</span>logger<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">recovery</span><span class="token punctuation">(</span>logger<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Так будут два logger и два recovery middleware. Выберите <code>gin.Default()</code> с настройками по умолчанию <strong>или</strong> <code>gin.New()</code> с явной цепочкой. В этом проекте используется второй вариант.</p><h3 id="отдавать-panic-клиенту" tabindex="-1"><a class="header-anchor" href="#отдавать-panic-клиенту"><span>Отдавать panic клиенту</span></a></h3><p>Не записывайте <code>fmt.Sprint(recovered)</code> в JSON. Логируйте подробность на сервере и возвращайте клиенту нейтральный <code>500</code>.</p><h3 id="пропустить-строгую-проверку-json" tabindex="-1"><a class="header-anchor" href="#пропустить-строгую-проверку-json"><span>Пропустить строгую проверку JSON</span></a></h3><p>Если API ранее отвергал неизвестные поля, включите <code>gin.EnableJsonDecoderDisallowUnknownFields()</code> и добавьте тест. Иначе опечатка клиента может стать тихой ошибкой.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>HTTP-слой Task Manager API теперь основан на Gin. В следующей главе изучим стандартный <code>http.Client</code> и научимся безопасно вызывать внешние HTTP API с context, таймаутами и проверкой статусов.</p>`,99)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};